SELECT 'challenge_video_overlays' as tbl, count(*) as cnt FROM app.challenge_video_overlays UNION ALL SELECT 'challenge_video_render_jobs', count(*) FROM app.challenge_video_render_jobs UNION ALL SELECT 'challenge_participation_videos', count(*) FROM app.challenge_participation_videos UNION ALL SELECT 'free_videos', count(*) FROM app.free_videos UNION ALL SELECT 'free_video_overlays', count(*) FROM app.free_video_overlays UNION ALL SELECT 'free_video_render_jobs', count(*) FROM app.free_video_render_jobs UNION ALL SELECT 'video_shares', count(*) FROM app.video_shares UNION ALL SELECT 'video_reactions', count(*) FROM app.video_reactions UNION ALL SELECT 'video_assets', count(*) FROM app.video_assets UNION ALL SELECT 'video_views', count(*) FROM app.video_views UNION ALL SELECT 'video_likes', count(*) FROM app.video_likes UNION ALL SELECT 'video_comments', count(*) FROM app.video_comments ORDER BY tbl;
